2|
3|namespace App\Http\Controllers\Api;
4|
5|use App\Http\Controllers\Controller;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Jobs\SendNotificationJob;
8|use App\Models\Ticket;
9|use App\Models\TicketComment;
10|use App\Models\TicketCommentReaction;
11|use App\Models\User;
12|use Illuminate\Http\JsonResponse;
13|use Illuminate\Support\Facades\DB;
14|
15|class TicketCommentController extends Controller
16|{
17|    /**
18|     * Issue #863: hard cap on how many `@handle`s one comment may resolve to.
19|     *
20|     * A body is capped at `max:10000` characters and every valid handle is
21|     * 11 characters (`@` + a 10-digit n_code, `\w+` stops at the next
22|     * non-word character so no separator is needed), so ONE maximum-length
23|     * comment fits 909 distinct handles — measured, not estimated. Without a
24|     * bound that becomes 909 `IN` values and 909 queued `SendNotificationJob`s
25|     * from a single request on a route gated only by `create_ticket`, which
26|     * the lowest role holds.
27|     *
28|     * The cap is applied to the MATCHED HANDLES, before the database lookup,
29|     * not to the notifications actually created: the amplification is the
30|     * 909-element `whereIn` plus one job per match, and unmatched handles are
31|     * the majority of any spam attempt, so counting only the recipients that
32|     * resolved would let unknown names consume the whole quota.
33|     */
34|    public const MAX_MENTIONS = 20;
35|
36|    /**
37|     * List comments for a ticket.
38|     */
39|    public function index(UnitScopedRequest $request, Ticket $ticket): JsonResponse
40|    {
41|        $accessibleIds = $request->accessibleIds();
42|
43|        if (! in_array($ticket->unit_id, $accessibleIds)) {
44|            return response()->json(['message' => 'Ticket not accessible.'], 403);
45|        }
46|
47|        $threaded = $request->boolean('threaded');
48|        $perPage = min($request->integer('per_page', 20), 100);
49|
50|        $query = $ticket->comments()
51|            ->with(['user:id,n_code', 'reactions'])
52|            ->whereNull('parent_id')
53|            ->latest();
54|
55|        if ($threaded) {
56|            $comments = $query->with('children.user', 'children.reactions')
57|                ->paginate($perPage);
58|        } else {
59|            $comments = $query->paginate($perPage);
60|        }
61|
62|        return response()->json([
63|            'data' => $comments->items(),
64|            'meta' => [
65|                'current_page' => $comments->currentPage(),
66|                'last_page' => $comments->lastPage(),
67|                'per_page' => $comments->perPage(),
68|                'total' => $comments->total(),
69|            ],
70|        ]);
71|    }
72|
73|    /**
74|     * Create a new comment on a ticket.
75|     */
76|    public function store(UnitScopedRequest $request, Ticket $ticket): JsonResponse
77|    {
78|        $accessibleIds = $request->accessibleIds();
79|
80|        if (! in_array($ticket->unit_id, $accessibleIds)) {
81|            return response()->json(['message' => 'Ticket not accessible.'], 403);
82|        }
83|
84|        $validated = $request->validate([
85|            'body' => 'required|string|max:10000',
86|            'parent_id' => 'nullable|exists:ticket_comments,id',
87|        ]);
88|
89|        // If parent_id provided, verify it belongs to same ticket
90|        if ($validated['parent_id'] ?? null) {
91|            $parent = TicketComment::find($validated['parent_id']);
92|            if (! $parent || $parent->ticket_id !== $ticket->id) {
93|                return response()->json(['message' => 'Invalid parent comment.'], 422);
94|            }
95|            // Limit thread depth to 3
96|            $depth = $this->getThreadDepth($parent);
97|            if ($depth >= 3) {
98|                return response()->json(['message' => 'Maximum thread depth reached (3).'], 422);
99|            }
100|        }
101|
102|        // Process @mentions and markdown
103|        $bodyHtml = $this->processMarkdown($validated['body']);
104|        $mentions = $this->extractMentions($validated['body'], $accessibleIds);
105|
106|        $comment = TicketComment::create([
107|            'ticket_id' => $ticket->id,
108|            'user_id' => $request->user()->id,
109|            'parent_id' => $validated['parent_id'] ?? null,
110|            'body' => $validated['body'],
111|            'body_html' => $bodyHtml,
112|            'is_system' => false,
113|        ]);
114|
115|        // Notify mentioned users
116|        if (! empty($mentions)) {
117|            $this->notifyMentions($mentions, $comment, $request->user());
118|        }
119|
120|        // Notify parent comment author (if reply)
121|        if ($comment->parent_id) {
122|            $parentComment = TicketComment::find($comment->parent_id);
123|            if ($parentComment && $parentComment->user_id !== $request->user()->id) {
124|                $this->notifyReply($parentComment, $comment, $request->user());
125|            }
126|        }
127|
128|        return response()->json([
129|            'success' => true,
130|            'data' => $comment->load(['user:id,n_code', 'reactions']),
131|        ], 201);
132|    }
133|
134|    /**
135|     * Show a single comment.
136|     */
137|    public function show(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
138|    {
139|        $accessibleIds = $request->accessibleIds();
140|
141|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
142|            return response()->json(['message' => 'Comment not accessible.'], 403);
143|        }
144|
145|        return response()->json([
146|            'data' => $comment->load(['user:id,n_code', 'reactions', 'children.user:id,n_code']),
147|        ]);
148|    }
149|
150|    /**
151|     * Update a comment (author only, within 15 minutes).
152|     */
153|    public function update(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
154|    {
155|        $accessibleIds = $request->accessibleIds();
156|
157|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
158|            return response()->json(['message' => 'Comment not accessible.'], 403);
159|        }
160|
161|        if (! $comment->canBeEditedBy($request->user())) {
162|            return response()->json(['message' => 'Cannot edit this comment.'], 403);
163|        }
164|
165|        $validated = $request->validate([
166|            'body' => 'required|string|max:10000',
167|        ]);
168|
169|        $comment->update([
170|            'body' => $validated['body'],
171|            'body_html' => $this->processMarkdown($validated['body']),
172|        ]);
173|
174|        return response()->json([
175|            'success' => true,
176|            'data' => $comment->fresh()->load(['user:id,n_code', 'reactions']),
177|        ]);
178|    }
179|
180|    /**
181|     * Soft delete a comment (author or admin).
182|     */
183|    public function destroy(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
184|    {
185|        $accessibleIds = $request->accessibleIds();
186|
187|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
188|            return response()->json(['message' => 'Comment not accessible.'], 403);
189|        }
190|
191|        if (! $comment->canBeDeletedBy($request->user())) {
192|            return response()->json(['message' => 'Cannot delete this comment.'], 403);
193|        }
194|
195|        $comment->delete();
196|
197|        return response()->json(['success' => true]);
198|    }
199|
200|    /**
201|     * Add a reaction to a comment.
202|     */
203|    public function react(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
204|    {
205|        $accessibleIds = $request->accessibleIds();
206|
207|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
208|            return response()->json(['message' => 'Comment not accessible.'], 403);
209|        }
210|
211|        $validated = $request->validate([
212|            'reaction' => 'required|string|in:+1,-1,heart,tada,rocket,eyes',
213|        ]);
214|
215|        $reaction = TicketCommentReaction::firstOrCreate([
216|            'comment_id' => $comment->id,
217|            'user_id' => $request->user()->id,
218|            'reaction' => $validated['reaction'],
219|        ]);
220|
221|        // Notify comment author (batched - could be improved with a job)
222|        if ($comment->user_id !== $request->user()->id) {
223|            $this->notifyReaction($comment, $request->user(), $validated['reaction']);
224|        }
225|
226|        return response()->json([
227|            'success' => true,
228|            'data' => $reaction,
229|        ]);
230|    }
231|
232|    /**
233|     * Remove a reaction from a comment.
234|     */
235|    public function unreact(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
236|    {
237|        $accessibleIds = $request->accessibleIds();
238|
239|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
240|            return response()->json(['message' => 'Comment not accessible.'], 403);
241|        }
242|
243|        $validated = $request->validate([
244|            'reaction' => 'required|string|in:+1,-1,heart,tada,rocket,eyes',
245|        ]);
246|
247|        TicketCommentReaction::where([
248|            'comment_id' => $comment->id,
249|            'user_id' => $request->user()->id,
250|            'reaction' => $validated['reaction'],
251|        ])->delete();
252|
253|        return response()->json(['success' => true]);
254|    }
255|
256|    /**
257|     * List reactions on a comment with counts.
258|     */
259|    public function reactions(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
260|    {
261|        $accessibleIds = $request->accessibleIds();
262|
263|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
264|            return response()->json(['message' => 'Comment not accessible.'], 403);
265|        }
266|
267|        $reactions = $comment->reactions()
268|            ->with('user:id,n_code')
269|            ->get()
270|            ->groupBy('reaction')
271|            ->map(function ($group) {
272|                return [
273|                    'count' => $group->count(),
274|                    'users' => $group->map->user,
275|                ];
276|            });
277|
278|        return response()->json([
279|            'data' => $reactions,
280|        ]);
281|    }
282|
283|    /**
284|     * Calculate thread depth in a single query (recursive CTE) — Issue #392.
285|     */
286|    private function getThreadDepth(TicketComment $comment): int
287|    {
288|        $depth = DB::selectOne(
289|            'WITH RECURSIVE cte AS (
290|                SELECT id, parent_id, 0 AS depth FROM ticket_comments WHERE id = ?
291|                UNION ALL
292|                SELECT tc.id, tc.parent_id, cte.depth + 1
293|                FROM ticket_comments tc
294|                INNER JOIN cte ON tc.id = cte.parent_id
295|            )
296|            SELECT MAX(depth) AS max_depth FROM cte',
297|            [$comment->id]
298|        );
299|
300|        return (int) ($depth->max_depth ?? 0);
301|    }
302|
303|    /**
304|     * Sanitize URL by blocking dangerous protocols and escaping attribute-breaking characters.
305|     * Fixes Issue #458: XSS via unquoted HTML event attributes in URLs (e.g., `onmouseover=alert(1)`).
306|     */
307|    private function sanitizeUrl(string $url): string
308|    {
309|        $url = trim($url);
310|        $dangerousProtocols = ['javascript:', 'data:', 'vbscript:', 'file:', 'about:'];
311|
312|        foreach ($dangerousProtocols as $proto) {
313|            if (stripos($url, $proto) === 0) {
314|                return '#';
315|            }
316|        }
317|
318|        // Only allow http, https, mailto, tel
319|        if (! preg_match('/^(https?|mailto|tel):/i', $url)) {
320|            return '#';
321|        }
322|
323|        // Escape any remaining dangerous chars in the URL value (e.g., spaces, quotes, angle brackets)
324|        return htmlspecialchars($url, ENT_QUOTES | ENT_HTML5, 'UTF-8');
325|    }
326|
327|    /**
328|     * Process markdown to HTML (simple implementation).
329|     */
330|    private function processMarkdown(string $body): string
331|    {
332|        // Basic markdown processing - in production use a proper parser like league/commonmark
333|        $html = e($body);
334|        $html = preg_replace('/\*\*(.+?)\*\*/', '<strong>$1</strong>', $html);
335|        $html = preg_replace('/\*(.+?)\*/', '<em>$1</em>', $html);
336|        $html = preg_replace('/`(.+?)`/', '<code>$1</code>', $html);
337|        $html = preg_replace_callback(
338|            '/\[(.+?)\]\((.+?)\)/',
339|            // Issue #425: URL goes through sanitizeUrl() which strips any character that could
340|            // break out of the href="..." attribute (quotes, angle brackets, control chars).
341|            // Note: $body is e()-escaped before this, so this is an extra defense-in-depth layer.
342|            fn ($m) => '<a href="'.$this->sanitizeUrl($m[2]).'" target="_blank" rel="noopener">'.$m[1].'</a>',
343|            $html
344|        );
345|        $html = preg_replace('/^> (.+)$/m', '<blockquote>$1</blockquote>', $html);
346|        $html = preg_replace('/^- (.+)$/m', '<li>$1</li>', $html);
347|        $html = preg_replace('/(<li>.*<\/li>)/s', '<ul>$1</ul>', $html);
348|        $html = nl2br($html);
349|
350|        return $html;
351|    }
352|
353|    /**
354|     * Extract @mentions from body, capped and unit-scoped (issue #863).
355|     *
356|     * Two independent bounds, both applied BEFORE the lookup so neither the
357|     * `whereIn` nor the job count can be inflated by the other:
358|     *
359|     * 1. `MAX_MENTIONS` on the matched handles — the amplification is a
360|     *    909-value `IN` list, not the notifications, so the cap sits here.
361|     * 2. The author's own `accessibleUnitIds()` — a mention can only reach a user
362|     *    whose linked person sits in a unit the author can see, which is the same
363|     *    contract every other user-visible query in the app follows. A target the
364|     *    author cannot read must not be able to receive a notification about a
365|     *    comment they will never see.
366|     *
367|     * The unit predicate is an UNCONDITIONAL `whereIn`, never `when($ids, …)` or
368|     * `! empty($ids)`: `accessibleUnitIds()` is legitimately `[]` for an account
369|     * with no `user_units` row and no `person.u_id`, and `[]` must compile to
370|     * `0 = 1` (zero recipients), not to "no restriction". A NULL `persons.u_id`
371|     * never matches a `whereIn`, so a unit-less person is in scope of nothing —
372|     * also fail-closed, and deliberate.
373|     *
374|     * @param  array<int>  $accessibleIds
375|     * @return array<string, int> n_code => user id
376|     */
377|    private function extractMentions(string $body, array $accessibleIds): array
378|    {
379|        preg_match_all('/@(\w+)/', $body, $matches);
380|
381|        // `true` preserves the n_code keys notifyMentions() re-emits as the
382|        // notification body, and `array_slice` bounds the `whereIn` below.
383|        $usernames = array_slice(array_unique($matches[1] ?? []), 0, self::MAX_MENTIONS, true);
384|
385|        if ($usernames === []) {
386|            return [];
387|        }
388|
389|        return User::query()
390|            // The IN-filter lives inside a `where()` closure on purpose: a
391|            // top-level `whereIn()` re-types the chain to Query\Builder (no
392|            // larastan), which makes the `whereHas()` below unresolvable.
393|            ->where(fn ($userQuery) => $userQuery->whereIn('n_code', $usernames))
394|            ->whereHas('person', fn ($personQuery) => $personQuery->whereIn('u_id', $accessibleIds))
395|            ->pluck('id', 'n_code')
396|            ->all();
397|    }
398|
399|    /**
400|     * Notify mentioned users.
401|     */
402|    private function notifyMentions(array $mentions, TicketComment $comment, User $author): void
403|    {
404|        foreach ($mentions as $username => $userId) {
405|            if ($userId === $author->id) {
406|                continue;
407|            }
408|
409|            SendNotificationJob::dispatch(
410|                $userId,
411|                'mention',
412|                "شما در یک نظر به تیکت {$comment->ticket->ticket_code} منشن شدید",
413|                'منشن در نظر',
414|                'at-sign',
415|                'text-blue-500',
416|                route('tickets.inbox', $comment->ticket_id)
417|            );
418|        }
419|    }
420|
421|    /**
422|     * Notify parent comment author of reply.
423|     */
424|    private function notifyReply(TicketComment $parentComment, TicketComment $reply, User $author): void
425|    {
426|        SendNotificationJob::dispatch(
427|            $parentComment->user_id,
428|            'reply',
429|            "{$author->n_code} به نظر شما در تیکت {$reply->ticket->ticket_code} پاسخ داد",
430|            'پاسخ به نظر',
431|            'message-circle',
432|            'text-green-500',
433|            route('tickets.inbox', $reply->ticket_id)
434|        );
435|    }
436|
437|    /**
438|     * Notify comment author of reaction.
439|     */
440|    private function notifyReaction(TicketComment $comment, User $reactor, string $reaction): void
441|    {
442|        if ($comment->user_id === $reactor->id) {
443|            return;
444|        }
445|
446|        $emojiMap = [
447|            '+1' => '👍',
448|            '-1' => '👎',
449|            'heart' => '❤️',
450|            'tada' => '🎉',
451|            'rocket' => '🚀',
452|            'eyes' => '👀',
453|        ];
454|
455|        $emoji = $emojiMap[$reaction] ?? $reaction;
456|
457|        SendNotificationJob::dispatch(
458|            $comment->user_id,
459|            'reaction',
460|            "{$reactor->n_code} واکنش {$emoji} را به نظر شما در تیکت {$comment->ticket->ticket_code} اضافه کرد",
461|            'واکنش جدید',
462|            'smile',
463|            'text-yellow-500',
464|            route('tickets.inbox', $comment->ticket_id)
465|        );
466|    }
