12|class TodoController extends Controller
13|{
14|    public function index(UnitScopedRequest $request): AnonymousResourceCollection
15|    {
16|        $accessibleIds = $request->accessibleIds();
17|
18|        $query = Todo::whereIn('unit_id', $accessibleIds)->with('unit:id,name');
19|
20|        if ($request->filled('date')) {
21|            $query->whereDate('start_at', $request->date);
22|        }
23|
24|        if ($request->filled('month') && $request->filled('year')) {
25|            $query->whereMonth('start_at', $request->month)
26|                ->whereYear('start_at', $request->year);
27|        }
28|
29|        if ($request->filled('is_completed')) {
30|            $query->where('is_completed', $request->boolean('is_completed'));
31|        }
32|
33|        $perPage = min((int) $request->input('per_page', 15), 100);
34|        $todos = $query->latest()->paginate($perPage);
35|
36|        return TodoResource::collection($todos);
37|    }
38|
39|    public function store(UnitScopedRequest $request): JsonResponse
40|    {
41|        $validated = $request->validate([
42|            'title' => 'required|string|min:3',
43|            'start_at' => 'required|date',
44|            'end_at' => 'nullable|date|after_or_equal:start_at',
45|            'is_completed' => 'boolean',
46|            'unit_id' => 'nullable|exists:units,id',
47|        ]);
48|
49|        $user = $request->user();
50|
51|        // Explicit unit_id wins; fall back to the user's primary unit (pivot is_primary),
52|        // then to the person's unit — never silently null (#431)
53|        $unitId = $validated['unit_id'] ?? $user->primaryUnit()?->id ?? $user->person?->u_id;
54|
55|        if (! $unitId || ! in_array($unitId, $request->accessibleIds())) {
56|            return response()->json(['message' => 'Unauthorized to create todo in this unit.'], 403);
57|        }
58|
59|        $todo = Todo::create([
60|            'title' => $validated['title'],
61|            'start_at' => $validated['start_at'],
62|            'end_at' => $validated['end_at'] ?? null,
63|            'is_completed' => $validated['is_completed'] ?? false,
64|            'unit_id' => $unitId,
65|            'user_id' => $user->id,
66|        ]);
67|
68|        return response()->json([
69|            'success' => true,
70|            'data' => new TodoResource($todo->load('unit')),
71|        ], 201);
72|    }
