     5	use Closure;
     6	use Illuminate\Http\Request;
     7	use Symfony\Component\HttpFoundation\Response;
     8	
     9	class SecurityHeaders
    10	{
    11	    public function handle(Request $request, Closure $next): Response
    12	    {
    13	        $response = $next($request);
    14	
    15	        $response->headers->set('X-Content-Type-Options', 'nosniff');
    16	        $response->headers->set('X-Frame-Options', 'DENY');
    17	        $response->headers->set('Referrer-Policy', 'strict-origin-when-cross-origin');
    18	
    19	        // CSP in report-only mode first — validate for 1-2 weeks before enforcing.
    20	        // `report-uri` is deprecated and ignored by modern Chrome, so it is gone:
    21	        // violations go through the Reporting API (`report-to` directive plus
    22	        // this Reporting-Endpoints header) to POST /csp-report (#742). The
    23	        // same-app destination is temporary — the final target is a
    24	        // separate-domain endpoint (decision recorded on issue #742).
    25	        $response->headers->set('Content-Security-Policy-Report-Only', "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https:; connect-src 'self'; font-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'; report-to csp-endpoint");
    26	        $response->headers->set('Reporting-Endpoints', 'csp-endpoint="/csp-report"');
    27	
    28	        $response->headers->set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
    29	
    30	        return $response;
    31	    }
