    10	use Illuminate\Support\Facades\Cache;
    11	
    12	class LastUserActivity
    13	{
    14	    /**
    15	     * The cache key prefix for user activity
    16	     */
    17	    const CACHE_KEY_PREFIX = 'user:activity:';
    18	
    19	    /**
    20	     * The duration in minutes to consider user as online
    21	     */
    22	    const ONLINE_DURATION = 3;
    23	
    24	    /**
    25	     * Handle an incoming request.
    26	     *
    27	     * @param  Closure(Request): (Response|RedirectResponse)  $next
    28	     * @return Response|RedirectResponse
    29	     */
    30	    public function handle(Request $request, Closure $next)
    31	    {
    32	        if (Auth::check()) {
    33	            $this->updateLastActivity(Auth::id());
    34	        }
    35	
    36	        return $next($request);
    37	    }
    38	
    39	    /**
    40	     * Update the user's last activity timestamp in cache
    41	     */
    42	    protected function updateLastActivity(int $userId): void
    43	    {
    44	        $key = self::CACHE_KEY_PREFIX.$userId;
    45	
    46	        // Skip write if key already exists — reduces cache writes to once per ONLINE_DURATION
    47	        if (Cache::has($key)) {
    48	            return;
    49	        }
    50	
    51	        Cache::put(
    52	            $key,
    53	            now()->toDateTimeString(),
    54	            now()->addMinutes(self::ONLINE_DURATION)
    55	        );
    56	    }
    57	}
