63|    private function assertAccessible(UnitScopedRequest $request, Hardware $hardware): void
64|    {
65|        $accessibleIds = $request->accessibleIds();
66|
67|        $unitId = $hardware->relationLoaded('person')
68|            ? $hardware->person?->u_id
69|            : $hardware->person()->value('u_id');
70|
71|        if (! $unitId || ! in_array($unitId, $accessibleIds)) {
