141|        $sortDir = strtolower($request->get('sort_dir', 'desc'));
142|        if (! in_array($sortDir, ['asc', 'desc'])) {
143|            $sortDir = 'desc';
144|        }
145|
146|        $query->orderBy($sortBy, $sortDir);
147|
148|        $perPage = min((int) $request->get('per_page', 10), 100);
149|
150|        $paginator = $query->paginate($perPage);
