251|
252|        $data = Cache::remember($cacheKey, now()->addMinutes(10), function () use ($accessibleIds) {
253|            $baseQuery = Hardware::join('persons', 'hardwares.n_code', '=', 'persons.n_code')
254|                ->whereIn('persons.u_id', $accessibleIds)
