60|        if (! empty($validated['parent_id']) && ! in_array($validated['parent_id'], $accessibleIds)) {
61|            return response()->json(['message' => 'Parent unit not accessible.'], 403);
62|        }
63|
64|        $unit = Unit::create($validated);
65|
66|        // Invalidate AccessService cache if hierarchy changed (new child created)
67|        if (! empty($unit->parent_id)) {
68|            app(AccessService::class)->clearAllCaches();
69|        }
70|
71|        return response()->json([
72|            'success' => true,
73|            'data' => $unit,
74|        ], 201);
