77|    public function update(UnitScopedRequest $request, Unit $unit): JsonResponse
78|    {
79|        $ids = $request->accessibleIds();
80|
81|        if (! in_array($unit->id, $ids)) {
82|            return response()->json(['message' => 'Unit not accessible.'], 403);
83|        }
84|
85|        $validated = $request->validate([
86|            'name' => 'sometimes|required|string|max:255',
87|            'description' => 'nullable|string',
88|            'region_id' => 'nullable|exists:regions,id',
89|            'parent_id' => 'nullable|exists:units,id',
90|            'unit_type_id' => 'sometimes|required|exists:unit_types,id',
91|            'lat' => 'nullable|numeric|between:-90,90',
92|            'lng' => 'nullable|numeric|between:-180,180',
93|        ]);
94|
95|        // Check organizational scope for parent_id
96|        $accessibleIds = $request->accessibleIds();
