19|class ReportController extends Controller
20|{
21|    public function __construct(
22|        protected CacheInvalidationServiceInterface $cache
23|    ) {}
24|
25|    public function units(UnitScopedRequest $request): JsonResponse
26|    {
27|        $accessibleIds = $request->accessibleIds();
28|        $scopeHash = md5(json_encode($accessibleIds));
29|
30|        $data = $this->cache->remember('report_units', $scopeHash, function () use ($accessibleIds) {
31|            // Single query: total + with_boundary via conditional aggregation (was 2 count queries)
32|            $stats = Unit::whereIn('id', $accessibleIds)
33|                ->selectRaw('COUNT(*) as total, SUM(CASE WHEN boundary_id IS NOT NULL THEN 1 ELSE 0 END) as with_boundary')
34|                ->first();
35|
36|            $total = (int) $stats->total;
37|            $withBoundary = (int) $stats->with_boundary;
38|            $withoutBoundary = $total - $withBoundary;
39|
40|            $byType = Unit::query()
41|                ->selectRaw('COALESCE(unit_types.name, ?) as type_name, COUNT(units.id) as count', ['نامشخص'])
42|                ->leftJoin('unit_types', 'units.unit_type_id', '=', 'unit_types.id')
43|                ->whereIn('units.id', $accessibleIds)
44|                ->groupBy('type_name')
45|                ->pluck('count', 'type_name')
46|                ->toArray();
47|
48|            return [
49|                'total' => $total,
50|                'with_boundary' => $withBoundary,
51|                'without_boundary' => $withoutBoundary,
52|                'by_type' => $byType,
53|            ];
54|        }, 10);
55|
56|        return response()->json($data);
57|    }
58|
59|    public function todos(UnitScopedRequest $request): JsonResponse
60|    {
61|        $days = $this->days($request);
62|        $accessibleIds = $request->accessibleIds();
63|        $scopeHash = md5(json_encode($accessibleIds));
64|
65|        $data = $this->cache->remember('report_todos', $scopeHash, function () use ($accessibleIds, $days) {
66|            $now = now();
67|            $query = Todo::whereIn('unit_id', $accessibleIds);
68|
69|            // Single query: completed/pending/overdue via conditional aggregation (was 3 count queries)
70|            $stats = (clone $query)
71|                ->selectRaw(
72|                    'SUM(CASE WHEN is_completed THEN 1 ELSE 0 END) as completed, '
73|                    .'SUM(CASE WHEN NOT is_completed THEN 1 ELSE 0 END) as pending, '
74|                    .'SUM(CASE WHEN NOT is_completed AND end_at IS NOT NULL AND end_at < ? THEN 1 ELSE 0 END) as overdue',
75|                    [$now]
76|                )
77|                ->first();
78|
79|            $byDay = $this->dailySeries($days, $query, 'start_at');
80|
81|            $byUnit = Todo::selectRaw('COALESCE(units.name, ?) as unit_name, COUNT(*) as count', ['نامشخص'])
82|                ->whereIn('todos.unit_id', $accessibleIds)
83|                ->leftJoin('units', 'todos.unit_id', '=', 'units.id')
84|                ->groupBy('unit_name')
85|                ->pluck('count', 'unit_name')
86|                ->toArray();
87|
88|            return [
89|                'completed' => (int) $stats->completed,
90|                'pending' => (int) $stats->pending,
91|                'overdue' => (int) $stats->overdue,
92|                'by_day' => $byDay,
93|                'by_unit' => $byUnit,
94|            ];
95|        }, 10, ['days' => $days]);
96|
97|        return response()->json($data);
98|    }
99|
100|    public function tickets(UnitScopedRequest $request): JsonResponse
101|    {
102|        $days = $this->days($request);
103|        $accessibleIds = $request->accessibleIds();
104|        $scopeHash = md5(json_encode($accessibleIds));
105|
106|        $data = $this->cache->remember('report_tickets', $scopeHash, function () use ($accessibleIds, $days) {
107|            $query = Ticket::whereIn('unit_id', $accessibleIds);
108|
109|            $byStatus = (clone $query)
110|                ->selectRaw('status, count(*) as count')
111|                ->groupBy('status')
112|                ->pluck('count', 'status')
113|                ->toArray();
114|
115|            $byPriority = (clone $query)
116|                ->selectRaw('priority, count(*) as count')
117|                ->groupBy('priority')
118|                ->pluck('count', 'priority')
119|                ->toArray();
120|
121|            $byDay = $this->dailySeries($days, $query, 'created_at');
122|
123|            return [
124|                'total' => array_sum($byStatus),
125|                'by_status' => $byStatus,
126|                'by_priority' => $byPriority,
127|                'by_day' => $byDay,
128|            ];
129|        }, 10, ['days' => $days]);
130|
131|        return response()->json($data);
132|    }
133|
134|    /**
135|     * Resolve and validate the `?days=` window (default 30, cap 365).
136|     *
137|     * The UI and the API used to disagree about what a daily chart covered —
138|     * the UI clipped to 30 while the API aggregated the whole history — so both
139|     * now take the window from here.
140|     */
141|    private function days(UnitScopedRequest $request): int
142|    {
143|        $request->validate(['days' => ['sometimes', new ReportDays]]);
144|
145|        return DailySeries::resolveDays($request->query('days'));
146|    }
147|
148|    /**
149|     * Daily counts as Jalali labels, one entry per day in the window.
150|     *
151|     * @param  EloquentBuilder<covariant Model>  $query  Already scoped to the caller's units
152|     * @return array<int, array{day: string, count: int}>
153|     */
154|    private function dailySeries(int $days, EloquentBuilder $query, string $dateColumn): array
155|    {
156|        return array_map(
157|            fn (array $row) => [
158|                'day' => Jalalian::fromCarbon(Carbon::parse($row['day']))->format('Y/m/d'),
159|                'count' => $row['count'],
160|            ],
161|            DailySeries::lastDays($days)->counts($query, $dateColumn)
162|        );
163|    }
