4|
5|use App\Exports\HardwareAuditsExport;
6|use App\Http\Controllers\Controller;
7|use App\Http\Requests\UnitScopedRequest;
8|use App\Models\Hardware;
9|use App\Models\HardwareAudit;
10|use App\Models\Person;
11|use App\Observers\HardwareAuditObserver;
12|use App\Services\HardwareAuditScope;
13|use Illuminate\Http\JsonResponse;
14|use Illuminate\Support\Facades\DB;
15|use Illuminate\Validation\Rule;
16|use Maatwebsite\Excel\Facades\Excel;
17|use Morilog\Jalali\Jalalian;
18|
19|class HardwareAuditController extends Controller
20|{
21|    /**
22|     * Display a paginated list of audits for a hardware item.
23|     */
24|    public function index(UnitScopedRequest $request, Hardware $hardware): JsonResponse
25|    {
26|        $this->assertAccessible($request, $hardware);
27|
28|        $query = HardwareAudit::where('hardware_id', $hardware->id)
29|            ->with('user.person:id,n_code,f_name,l_name')
30|            ->latest('created_at');
31|
32|        // Filters
33|        if ($request->filled('field')) {
34|            $query->whereJsonContains('changes', ['field' => $request->field]);
35|        }
36|        if ($request->filled('user_id')) {
37|            $query->where('user_id', $request->user_id);
38|        }
39|        if ($request->filled('date_from')) {
40|            $query->where('created_at', '>=', $request->date_from);
41|        }
42|        if ($request->filled('date_to')) {
43|            $query->where('created_at', '<=', $request->date_to);
44|        }
45|        if ($request->filled('action')) {
46|            $query->where('action', $request->action);
47|        }
48|        if ($request->filled('source')) {
49|            $query->where('source', $request->source);
50|        }
51|
52|        $perPage = min((int) $request->get('per_page', 20), 50);
53|        $audits = $query->paginate($perPage);
54|
55|        return response()->json([
56|            'data' => $audits->getCollection()->map(fn ($audit) => $this->transformAudit($audit))->all(),
57|            'meta' => [
58|                'current_page' => $audits->currentPage(),
59|                'last_page' => $audits->lastPage(),
60|                'per_page' => $audits->perPage(),
61|                'total' => $audits->total(),
62|            ],
63|        ]);
64|    }
65|
66|    /**
67|     * Display a single audit record with full diff.
68|     */
69|    public function show(UnitScopedRequest $request, Hardware $hardware, HardwareAudit $audit): JsonResponse
70|    {
71|        $this->assertAccessible($request, $hardware);
72|
73|        if ($audit->hardware_id !== $hardware->id) {
74|            return response()->json(['message' => 'Audit not found for this hardware.'], 404);
75|        }
76|
77|        $audit->load('user.person:id,n_code,f_name,l_name');
78|
79|        return response()->json([
80|            'data' => $this->transformAudit($audit, true),
81|        ]);
82|    }
83|
84|    /**
85|     * Rollback a specific field to its previous value.
86|     */
87|    public function rollback(UnitScopedRequest $request, Hardware $hardware, HardwareAudit $audit): JsonResponse
88|    {
89|        $this->assertAccessible($request, $hardware);
90|
91|        if ($audit->hardware_id !== $hardware->id) {
92|            return response()->json(['message' => 'Audit not found for this hardware.'], 404);
93|        }
94|
95|        $allowed = (new Hardware)->getFillable();
96|        $request->validate([
97|            'field' => ['required', 'string', Rule::in($allowed)],
98|        ]);
99|
100|        $changes = $audit->changes;
101|        if (! $changes || ! is_array($changes)) {
102|            return response()->json(['message' => 'No changes to rollback.'], 422);
103|        }
104|
105|        $fieldChange = null;
106|        foreach ($changes as $change) {
107|            if (($change['field'] ?? '') === $request->field) {
108|                $fieldChange = $change;
109|                break;
110|            }
111|        }
112|
113|        if (! $fieldChange) {
114|            return response()->json(['message' => 'Field not found in audit record.'], 422);
115|        }
116|
117|        $oldValue = $fieldChange['old'] ?? '—';
118|        $newValue = $fieldChange['new'] ?? '—';
119|
120|        // Parse the old value back to its original type
121|        $restoredValue = $this->parseValueForRestore($oldValue, $request->field);
122|
123|        // Verify target unit is accessible when restoring n_code
124|        if ($request->field === 'n_code' && $restoredValue !== null) {
125|            $person = Person::where('n_code', $restoredValue)->first();
126|            if (! $person) {
127|                return response()->json(['message' => 'Person not found.'], 422);
128|            }
129|            $accessibleIds = $request->accessibleIds();
130|            if (! in_array($person->u_id, $accessibleIds, true)) {
131|                return response()->json(['message' => 'Cannot restore hardware to a person in an inaccessible unit.'], 403);
132|            }
133|        }
134|
135|        // Update the hardware record
136|        $hardware->update([$request->field => $restoredValue]);
137|
138|        // Log the rollback as a new audit entry
139|        $rollbackChanges = [[
140|            'field' => $request->field,
141|            'old' => $newValue,
142|            'new' => $oldValue,
143|        ]];
144|
145|        app(HardwareAuditObserver::class)
146|            ->recordRollbackAudit($hardware, $rollbackChanges, $request->user()?->id);
147|
148|        return response()->json([
149|            'success' => true,
150|            'message' => "فیلد {$request->field} به مقدار قبلی بازگردانده شد.",
151|            'data' => [
152|                'field' => $request->field,
153|                'restored_value' => $oldValue,
154|            ],
155|        ]);
156|    }
157|
158|    /**
159|     * Restore a fully-deleted hardware record from its 'created' audit entry.
160|     *
161|     * Looks up the HardwareAudit row (which survives hard deletes) and
162|     * recreates the Hardware with the original field values.
163|     */
164|    public function restoreRecord(UnitScopedRequest $request, HardwareAudit $audit): JsonResponse
165|    {
166|        if ($audit->action !== 'created') {
167|            return response()->json(['message' => 'Only "created" audits can be used to restore a record.'], 422);
168|        }
169|
170|        // Verify the hardware was actually deleted. Use a direct query so this
171|        // works whether or not the Hardware model uses SoftDeletes.
172|        $exists = DB::table('hardwares')->where('id', $audit->hardware_id)->exists();
173|        if ($exists) {
174|            return response()->json(['message' => 'This hardware record still exists — use rollback instead.'], 422);
175|        }
176|
177|        // Verify the audit is not orphaned (linked hardware has never existed or no changes)
178|        if (! $audit->changes || ! is_array($audit->changes)) {
179|            return response()->json(['message' => 'No change data in audit to restore from.'], 422);
180|        }
181|
182|        $user = $request->user();
183|        $this->assertAccessibleFromAudit($request, $audit);
184|
185|        // Build restore data from the 'new' values of the 'created' audit
186|        $restoreData = [];
187|        foreach ($audit->changes as $change) {
188|            if (! isset($change['field'], $change['new'])) {
189|                continue;
190|            }
191|            $restoreData[$change['field']] = $this->parseValueForRestore(
192|                $change['new'],
193|                $change['field']
194|            );
195|        }
196|
197|        if (empty($restoreData)) {
198|            return response()->json(['message' => 'No field data found to restore.'], 422);
199|        }
200|
201|        $restoreData['id'] = $audit->hardware_id;
202|
203|        $hardware = Hardware::create($restoreData);
204|
205|        // Advance the Postgres sequence past the restored id so the next
206|        // auto-increment does not collide (duplicate key on hardwares_pkey).
207|        // pg_get_serial_sequence resolves the sequence name regardless of
208|        // SERIAL vs IDENTITY column definition.
209|        if (DB::connection()->getDriverName() === 'pgsql') {
210|            $seq = DB::selectOne("SELECT pg_get_serial_sequence('hardwares','id') as seq");
211|            if ($seq && $seq->seq) {
212|                DB::statement('SELECT setval(?, (SELECT COALESCE(MAX(id), 0) FROM hardwares))', [$seq->seq]);
213|            }
214|        }
215|
216|        // Note: Hardware::create() already fires HardwareAuditObserver::created()
217|        // (registered in AppServiceProvider), which writes the 'created' audit —
218|        // so we must NOT call it again here (would duplicate the audit row).
219|
220|        // Log an explicit 'rollback' audit for traceability
221|        $rollbackChanges = array_map(
222|            fn ($change) => ['field' => $change['field'], 'old' => 'حذف شده', 'new' => $change['new']],
223|            $audit->changes
224|        );
225|        app(HardwareAuditObserver::class)->recordRollbackAudit(
226|            $hardware,
227|            $rollbackChanges,
228|            $user?->id
229|        );
230|
231|        return response()->json([
232|            'success' => true,
233|            'message' => 'سخت‌افزار با موفقیت بازگردانده شد.',
